package dve_workspace

import (
	"net/http"

	"github.com/gorilla/mux"

	"backend_server/internal/web/middleware"
)

// RegisterRoutes registers all DVE service routes with the provided router
func (s *DVEService) RegisterRoutes(r *mux.Router, authMiddleware *middleware.AuthMiddleware) {
	// Create a subrouter for DVE endpoints
	dveRouter := r.PathPrefix("/dve").Subrouter()

	// Apply authentication middleware to all DVE routes
	dveRouter.Use(authMiddleware.RequireAuth)

	// Environment routes
	envRouter := dveRouter.PathPrefix("/environments").Subrouter()

// DVE Workspace Config Handlers

// HandleGetWorkspaceConfig returns the current DVE workspace configuration.
func (s *DVEService) HandleGetWorkspaceConfig(w http.ResponseWriter, r *http.Request) {
	s.mu.RLock()
	cfg := s.config
	s.mu.RUnlock()

	writeJSON(w, http.StatusOK, map[string]interface{}{
		"config": cfg,
	})
}

// HandleUpdateWorkspaceConfig hot-updates the DVE workspace configuration.
func (s *DVEService) HandleUpdateWorkspaceConfig(w http.ResponseWriter, r *http.Request) {
	var cfg DVEConfig
	if err := json.NewDecoder(r.Body).Decode(&cfg); err != nil {
		writeError(w, http.StatusBadRequest, "Invalid request body")
		return
	}

