// EnsureBusyBoxRootfs checks if the shared rootfs exists and is valid.
// Downloads + extracts busybox-static if missing.
// This runs once at DVEService startup, not per-workspace.
func EnsureBusyBoxRootfs(rootfsPath string, cfg DVEConfig) error {
	marker := filepath.Join(rootfsPath, ".knirvdve-ready")
	if _, err := os.Stat(marker); err == nil {
		return nil // already bootstrapped
	}
	log.Printf("DVEService: bootstrapping BusyBox rootfs at %s", rootfsPath)

	return env, nil
}

// createVirtualDVEAsync creates an isolated DVE workspace using
// OverlayFS + Linux user namespaces. Replaces the former eBPF placeholder.
func (s *DVEService) createVirtualDVEAsync(env *DVEEnvironment) {
	// 1. Ensure BusyBox rootfs is bootstrapped
	if s.config.EnableOverlayFS {
		if err := EnsureBusyBoxRootfs(s.config.BusyBoxRootfsPath, s.config); err != nil {
			env.Status = EnvStatusError
			log.Printf("DVEService: busybox rootfs bootstrap failed for %s: %v", env.ID, err)
			return
		}

		// 2. Allocate overlay workspace directories
		ws, err := NewOverlayWorkspace(s.config.WorkspaceRoot, s.config.BusyBoxRootfsPath, env.ID)
		if err != nil {
			env.Status = EnvStatusError
			log.Printf("DVEService: overlay workspace alloc failed for %s: %v", env.ID, err)

	}

	return nil
}

func main() {
	// Check for DVE namespace helper mode before any initialization.
	// The namespace helper is a re-execution of this binary inside new
	// user+mount namespaces. It performs the OverlayFS mount and blocks
	// until stdin is closed (teardown signal).
	if len(os.Args) > 1 && os.Args[1] == "--dve-ns-helper" {
		// Import must be available at runtime - this is the dve_workspace package
		// which is imported elsewhere in the binary.
		// We directly invoke the helper function from the dve_workspace package.
		// This is a blocking call - it mounts overlayfs then reads stdin.
		dve_workspace.NamespaceHelper()
		return
	}

