 // GetConfigDir returns the base configuration directory.
 func GetConfigDir() (string, error) {
 	if explicit := strings.TrimSpace(os.Getenv("KNIRV_CONFIG_DIR")); explicit != "" {
 		if err := os.MkdirAll(explicit, 0755); err != nil {
 			return "", fmt.Errorf("failed to create app config directory %s: %w", explicit, err)
 		}
 		return explicit, nil
 	}
 	if err := os.MkdirAll(defaultSystemConfigDir, 0755); err == nil {
 		return defaultSystemConfigDir, nil
 	}

 	userConfigDir, err := os.UserConfigDir()
 	if err != nil {
 		return "", fmt.Errorf("failed to get user config directory: %w", err)
 	}
 	appConfigDir := filepath.Join(userConfigDir, "knirv-server")
 	if err := os.MkdirAll(appConfigDir, 0755); err != nil {
 		return "", fmt.Errorf("failed to create app config directory %s: %w", appConfigDir, err)
 	}
 	return appConfigDir, nil
 }

 // GetExtractedConfigDir returns the embedded config export directory.
 func GetExtractedConfigDir() (string, error) {
 	configDir, err := GetConfigDir()
 	if err != nil {
 		return "", err
 	}

 	extractedConfigDir := filepath.Join(configDir, "config")
 	if err := os.MkdirAll(extractedConfigDir, 0755); err != nil {
 		return "", fmt.Errorf("failed to create extracted config directory %s: %w", extractedConfigDir, err)
 	}

 	return extractedConfigDir, nil
 }

 // GetDataDir returns the data directory path based on role
 func GetDataDir(role ...Role) (string, error) {
 	currentRole := RoleClient // Default
 	if len(role) > 0 {
 		currentRole = role[0]
 	}

 	baseDir := filepath.Join(defaultSystemAppDataDir, "backend_server")
 	if appDataDir, err := getAppDataDir(); err == nil {
 		baseDir = filepath.Join(appDataDir, "backend_server")
 	}

 	// Determine role-specific data directory name
 	var dataDirName string
 	switch currentRole {
 	case Root:
 		dataDirName = "root_data"
 	case RoleBootnode:
 		dataDirName = "bootnode_data"
 	case RolePeer:
 		dataDirName = "peer_data"
 	case RoleClient:
 		dataDirName = "client_data"
 	default:
 		dataDirName = "data" // Fallback
 	}

 	dataDirPath := filepath.Join(baseDir, dataDirName)
 	if err := os.MkdirAll(dataDirPath, 0755); err != nil {
 		if strings.TrimSpace(os.Getenv("KNIRV_APP_DATA_DIR")) == "" {
 			fallbackPath := filepath.Join(os.TempDir(), "knirvserver-fallback", "backend_server", dataDirName)
 			if fallbackErr := os.MkdirAll(fallbackPath, 0755); fallbackErr == nil {
 				return fallbackPath, nil
 			}
 		}
 		return "", fmt.Errorf("failed to create %s directory %s: %w", currentRole, dataDirPath, err)
 	}

 	return dataDirPath, nil
 }

 // validateConfig validates the loaded configuration
 func validateConfig(cfg *Config) error {
 	// Validate mode
 	if cfg.Mode != "headless" && cfg.Mode != "gui" {
 		return fmt.Errorf("mode must be 'headless' or 'gui', got: %s", cfg.Mode)
 	}

 	// Validate chain ID (use Network.ChainID if available, fallback to ChainID)
 	chainID := cfg.Network.ChainID
 	if chainID == "" {
 		chainID = cfg.ChainID
 	}
 	if chainID == "" {
 		return fmt.Errorf("chain_id is required")
 	}

 	if cfg.NodeRole == "" {
 		return fmt.Errorf("node_role is required")
 	}

 	if cfg.Database.Path == "" {
 		return fmt.Errorf("database.path is required")
 	}

 	// JWT secret validation - only required in headless mode or when auth is required
 	jwtSecret := cfg.Security.JWTSecret
 	if jwtSecret == "" {
 		jwtSecret = cfg.Auth.JWTSecret
 	}
 	if cfg.Mode == "headless" && cfg.Security.AuthRequired && jwtSecret == "" {
 		return fmt.Errorf("security.jwt_secret is required in headless mode with authentication")
 	}

 	// GUI mode specific validation
 	if cfg.Mode == "gui" && cfg.GUI.Enabled {
 		if cfg.GUI.Port <= 0 {
 			return fmt.Errorf("gui.port must be positive")
 		}
 		if cfg.GUI.FrontendPath == "" {
 			return fmt.Errorf("gui.frontend_path is required when GUI is enabled")
 		}
 	}

 	return nil
 }

