 // BuntDBManager manages the embedded BuntDB database
 type BuntDBManager struct {
 	db      *buntdb.DB
 	dbPath  string
 	indexes map[string]string
 	mu      sync.RWMutex
 }

 // BuntDB collections as defined in the NEXUS_MERGE.md
