 	}
 	return addr[:6] + "..." + addr[len(addr)-4:]
 }

 func formatTime(ts int64) string {
 	if ts == 0 {
 		return "\u2014"
 	}
 	return time.Unix(ts, 0).UTC().Format("2006-01-02")
 }

