 func TestNewServer_DatabaseError(t *testing.T) {
 	// Test with invalid database path
 	cfg := &config.Config{
 		Database: config.DatabaseConfig{
 			Path: "/invalid/path/test.db",
 		},
 		ChainID:  "test-chain",
 		NodeRole: "validator",
 		API: config.APIConfig{
