 func TestServerHandleHealth(t *testing.T) {
 	tmpDir := t.TempDir()
 	dbPath := filepath.Join(tmpDir, "test.db")

 	cfg := &config.Config{
 		Database: config.DatabaseConfig{
 			Path: dbPath,
