 func TestInitOracleManagerUsesAppDataSocketAndCloudflareEnv(t *testing.T) {
 	t.Setenv("KNIRV_APP_DATA_DIR", t.TempDir())

 	logger := zap.NewNop()
 	secrets := &pb.RootKeyFileContentProto{
 		CloudflareApiToken:   "cf-token",
