func TestMigrateCDEKeysToDVE(t *testing.T) {
	manager, db := NewTestBuntDBManager(t)

	// Insert legacy "cde_environments:" test records
	err := db.Update(func(tx *buntdb.Tx) error {
		_, _, err := tx.Set("cde_environments:env1", `{"id":"env1","name":"test-env"}`, nil)
		return err
	})
	require.NoError(t, err)

	err = db.Update(func(tx *buntdb.Tx) error {
		_, _, err = tx.Set("cde_environments:env2", `{"id":"env2","name":"dev-env"}`, nil)
		return err
	})
	require.NoError(t, err)

	// Insert legacy "cde_sessions:" test records
	err = db.Update(func(tx *buntdb.Tx) error {
		_, _, err := tx.Set("cde_sessions:sess1", `{"id":"sess1","user":"user1"}`, nil)
		return err
	})
	require.NoError(t, err)

	// Insert legacy "cde_projects:" test records
	err = db.Update(func(tx *buntdb.Tx) error {
		_, _, err := tx.Set("cde_projects:proj1", `{"id":"proj1","name":"my-project"}`, nil)
		return err
	})
	require.NoError(t, err)

	// Verify old records exist before migration
	var oldCount int
	err = db.View(func(tx *buntdb.Tx) error {
		err := tx.AscendKeys("cde_*", func(k, v string) bool {
			oldCount++
			return true
		})
		return err
	})
	require.NoError(t, err)
	require.Equal(t, 4, oldCount, "should have 4 legacy cde_ records before migration")

	// Verify new records do NOT exist before migration
	var newCountBefore int
	err = db.View(func(tx *buntdb.Tx) error {
		err := tx.AscendKeys("dve_*", func(k, v string) bool {
			newCountBefore++
			return true
		})
		return err
	})
	require.NoError(t, err)
	require.Equal(t, 0, newCountBefore, "should have 0 dve_ records before migration")

	// Run migration
	err = manager.MigrateCDEKeysToDVE()
	assert.NoError(t, err)

	// Verify old cde_ records are gone
	var oldCountAfter int
	err = db.View(func(tx *buntdb.Tx) error {
		err := tx.AscendKeys("cde_*", func(k, v string) bool {
			oldCountAfter++
			return true
		})
		return err
	})
	require.NoError(t, err)
	assert.Equal(t, 0, oldCountAfter, "all legacy cde_ records should be deleted")

	// Verify new dve_ records exist with correct values
	var newRecords []string
	err = db.View(func(tx *buntdb.Tx) error {
		return tx.AscendKeys("dve_*", func(k, v string) bool {
			newRecords = append(newRecords, k)
			return true
		})
	})
	require.NoError(t, err)
	assert.Equal(t, 4, len(newRecords), "should have 4 migrated dve_ records")

	assert.Contains(t, newRecords, "dve_environments:env1")
	assert.Contains(t, newRecords, "dve_environments:env2")
	assert.Contains(t, newRecords, "dve_sessions:sess1")
	assert.Contains(t, newRecords, "dve_projects:proj1")

	// Verify migrated data integrity by reading a specific record
	var env1Value string
	err = db.View(func(tx *buntdb.Tx) error {
		val, err := tx.Get("dve_environments:env1")
		if err != nil {
			return err
		}
		env1Value = val
		return nil
	})
	assert.NoError(t, err)
	assert.Equal(t, `{"id":"env1","name":"test-env"}`, env1Value, "migrated record value should match original")

	// Test idempotency: running migration again should not cause errors
	err = manager.MigrateCDEKeysToDVE()
	assert.NoError(t, err)

	// Verify records still exist after second migration
	var countAfterSecond int
	err = db.View(func(tx *buntdb.Tx) error {
		return tx.AscendKeys("dve_*", func(k, v string) bool {
			countAfterSecond++
			return true
		})
	})
	require.NoError(t, err)
	assert.Equal(t, 4, countAfterSecond, "records should survive a second migration call")
}

